import brand from '@/assets/img/logo/brand-logo3.png';
import { Link } from 'gatsby';
import React, { useEffect, useRef } from 'react';
import { Col, Container, Row } from 'react-bootstrap';
import { FaArrowRight } from 'react-icons/fa6';
import VanillaTilt from 'vanilla-tilt';

const Brands = () => {
  const tiltRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (tiltRef.current) {
      VanillaTilt.init(tiltRef.current, {
        max: 20,
        speed: 500,
        glare: true,
        'max-glare': 0.2,
        scale: 1.05,
        perspective: 1000,
      });
    }
  }, []);

  return (
    <>
      <div className="brand-area3 sp">
        <Container>
          <Row>
            <Col lg={4} className="m-auto text-center">
              <div className="headding3">
                <h2 data-aos="fade-up" data-aos-duration="900">
                  Elevate Your Brand with Our Solutions
                </h2>
                <div className="space10"></div>
                <p data-aos="fade-up" data-aos-duration="1100">
                  Save time and effort with our automation features. Routine SEO tasks are
                  streamlined, allowing you.
                </p>
                <div className="space20"></div>
                <div className="" data-aos="fade-up" data-aos-duration="900">
                  <Link to="/features" className="learn">
                    Explore Our Integration Library{' '}
                    <span>
                      <FaArrowRight />
                    </span>
                  </Link>
                </div>
              </div>
            </Col>
          </Row>

          <Row>
            <div
              ref={tiltRef}
              className="big-logo"
              data-tilt
              data-tilt-full-page-listening
              data-tilt-perspective="3000"
            >
              <img src={brand} alt="" />
            </div>
          </Row>
        </Container>
      </div>
    </>
  );
};

export default Brands;
