import img1 from '@/assets/img/pricing/pricing-img1.png';
import img2 from '@/assets/img/pricing/pricing-img2.png';
import img3 from '@/assets/img/pricing/pricing-img3.png';
import { Link } from 'gatsby';
import React, { useState } from 'react';
import { Col, Container, Row } from 'react-bootstrap';
import { FaArrowRight, FaCheck, FaXmark } from 'react-icons/fa6';

const Pricing = () => {
  const [isYearly, setIsYearly] = useState(true);

  type PricingPlan = {
    title: string;
    price: string;
    period: string;
    image: string;
  };

  type PricingData = {
    monthly: PricingPlan[];
    yearly: PricingPlan[];
  };

  const pricingData: PricingData = {
    monthly: [
      { title: 'Strater', price: '$11', period: 'Billed Monthly', image: img1 },
      { title: 'Business', price: '$44', period: 'Billed Monthly', image: img2 },
      { title: 'Elite/ Enterprise', price: '$78', period: 'Billed Monthly', image: img3 },
    ],
    yearly: [
      { title: 'Strater', price: '$29', period: 'Billed Yearly', image: img1 },
      { title: 'Business', price: '$249', period: 'Billed Yearly', image: img2 },
      { title: 'Elite/ Enterprise', price: '$499', period: 'Billed Yearly', image: img3 },
    ],
  };

  return (
    <div className="pricing-plan sp" id="pricing">
      <Container>
        <Row>
          <Col md={6} className="m-auto text-center">
            <div className="headding3">
              <h2 data-aos="fade-up" data-aos-duration="800">
                Compare The Plans
              </h2>
            </div>
          </Col>
        </Row>

        <div className="princing-plans">
          <Row>
            <Col className="text-center">
              <div className="plan-toggle-wrap" data-aos="fade-up" data-aos-duration="1000">
                <div className="pricing-btn-area">
                  <div className="toggle-inner home2-toggle-inner">
                    <input
                      id="ce-toggle"
                      type="checkbox"
                      checked={isYearly}
                      onChange={() => setIsYearly(!isYearly)}
                    />
                    <span className="custom-toggle"></span>
                    <span className="t-month">Monthly</span>
                    <span className="t-year">Yearly (Save 20%)</span>
                  </div>
                </div>
                <p>Save up to 32% with yearly billing.</p>
              </div>
            </Col>
          </Row>

          <div className="space60" /> 

          <Row>
            {(isYearly ? pricingData.yearly : pricingData.monthly).map((plan, idx) => (
              <Col md={6} lg={4} key={idx}>
                <div
                  className="pricing-box"
                  data-aos="fade-up"
                  data-aos-duration={1000 + idx * 100}
                >
                  <div className="pricing-box-single">
                    <div className="image">
                      <img src={plan.image} alt={plan.title} />
                    </div>
                    <h4>{plan.title}</h4>
                    <p>
                      Search engine ranks effortlessly with our a powerful and intuitive best
                      software eSoft
                    </p>
                    <p className="span-headding">
                      {plan.price} <span>/{plan.period}</span>
                    </p>

                    <ul className="list">
                      <li>
                        <span>
                          <FaCheck />
                        </span>{' '}
                        1 Project
                      </li>
                      <li>
                        <span>
                          <FaCheck />
                        </span>{' '}
                        1 User
                      </li>
                      <li>
                        <span>
                          <FaCheck />
                        </span>{' '}
                        10 K clicks/month
                      </li>
                      <li className="crose">
                        <span>
                          <FaXmark />
                        </span>{' '}
                        Download Data
                      </li>
                    </ul>

                    <div className="space20"></div>
                    <div className="button">
                      <Link className="immiPressBtn" to="/account">
                        <span>Start Free Trail</span>
                        <span className="arrow">
                          <FaArrowRight />
                        </span>
                      </Link>
                    </div>
                  </div>
                </div>
              </Col>
            ))}
          </Row>
        </div>
      </Container>
    </div>
  );
};

export default Pricing;
